mapper.select:
SELECT  FROM saves s
WHERE s.user_id = #{userId}
AND (s.created_at, s.id) < (#{beforeAt}, #{beforeId})

ORDER BY s.created_at DESC, s.id DESC
LIMIT #{limit}

SELECT s.kind AS kind, count(*) AS count FROM saves s
WHERE s.user_id = #{userId}

GROUP BY s.kind
